// Use — passes to next middleware
app.Use(async (context, next) => {
    Console.WriteLine("Before");
    await next();  // continue pipeline
    Console.WriteLine("After");
});

// Run — terminal, no next()
app.Run(async context => {
    await context.Response.WriteAsync("Hello!");
});

// Map — branch by path
app.Map("/health", branch => {
    branch.Run(async ctx => 
        await ctx.Response.WriteAsync("OK"));
});

var app = builder.Build();

app.UseExceptionHandler("/error");  // 1st — catches everything
app.UseHttpsRedirection();
app.UseStaticFiles();

app.UseRouting();          // matches endpoint
app.UseAuthentication();   // who are you? (JWT/Cookie)
app.UseAuthorization();    // are you allowed?

app.MapControllers();      // execute action
